#include <bits/stdc++.h>
using namespace std;

long long calculate(long long n) {
    int limit = 400000;
    std::vector<long long> upperPart(limit), lowerPart(limit);
    for (int i = 1; i < limit; ++i) {
        lowerPart[i] = i;
        upperPart[i] = n / i;
    }

    std::vector<bool> primeMarkers(limit, true);
    primeMarkers[0] = false;
    primeMarkers[1] = false;

    std::vector<int> primeNumbers;
    for (int i = 2; i < limit; ++i) {
        if (!primeMarkers[i]) continue;
        primeNumbers.push_back(i);
        for (int j = i * 2; j < limit; j += i) {
            primeMarkers[j] = false;
        }
    }

    for (size_t idx = 0; idx < primeNumbers.size(); ++idx) {
        int p = primeNumbers[idx];
        for (int i = 1; i < limit && n / i >= (long long)p * p; ++i) {
            long long val = (long long)p * i;
            if (val < limit) {
                upperPart[i] -= (upperPart[(int)val] - (idx + 1));
            } else {
                lowerPart[(int)(n / i / p)] -= (lowerPart[(int)(n / i / p)] - (idx + 1));
            }
        }
        for (int i = limit - 1; i >= (long long)p * p; --i) {
            lowerPart[i] -= lowerPart[i / p] - (idx + 1);
        }
    }

    long long total = 0;
    for (size_t i = 0; i < primeNumbers.size(); ++i) {
        int p = primeNumbers[i];
        if ((long long)p * p > n) break;
        if ((long long)p * p * p <= n && (long long)p * p * p > 0) {
            total++;
        }
        if (n / p > p) {
            if (p < limit)
                total += upperPart[p] - lowerPart[p];
            else
                total += lowerPart[(int)(n / p)] - lowerPart[p];
        }
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long inputNumber;
    cin >> inputNumber;
    cout << calculate(inputNumber) << "\n";
    return 0;
}

